        }
    }

    public static void main(String[] args) {
        check("class file path", "com/example/app/Main.class",
                ClassFilePathMapper.classFilePath("com.example.app.Main"));
        check("source file path", "com/example/app/Main.java",
                ClassFilePathMapper.sourceFilePath("com.example.app.Main"));
        check("default package class file", "Main.class", ClassFilePathMapper.classFilePath("Main"));
        check("package of qualified name", "com.example.app",
                ClassFilePathMapper.packageOf("com.example.app.Main"));
        check("package of default package name", "", ClassFilePathMapper.packageOf("Main"));
        check("simple name", "Main", ClassFilePathMapper.simpleNameOf("com.example.app.Main"));
        check("nested class path", "com/example/Outer$Inner.class",
                ClassFilePathMapper.classFilePath("com.example.Outer$Inner"));
        check("nested simple name", "Outer$Inner",
                ClassFilePathMapper.simpleNameOf("com.example.Outer$Inner"));
