public class ClassFilePathMapper {

    public static String classFilePath(String fullyQualifiedName) {
        return fullyQualifiedName.replace('.', '/') + ".class";
    }

    public static String sourceFilePath(String fullyQualifiedName) {
        return fullyQualifiedName.replace('.', '/') + ".java";
    }

    public static String packageOf(String fullyQualifiedName) {
        int lastDot = fullyQualifiedName.lastIndexOf('.');
        if (lastDot < 0) {
            return "";
        }
        return fullyQualifiedName.substring(0, lastDot);
    }

    public static String simpleNameOf(String fullyQualifiedName) {
        int lastDot = fullyQualifiedName.lastIndexOf('.');
        return fullyQualifiedName.substring(lastDot + 1);
    }
}
